/* From Uiverse.io by Ali-Tahmazi99 - Tags: loader */
.__UIV_SCOPE__ .loading {
  width: 60px;
  height: 60px;
  position: relative;
}

.__UIV_SCOPE__ .d1,
.__UIV_SCOPE__ .d2 {
  border: 5px solid #64dfdf;
  border-radius: 50px;
}

.__UIV_SCOPE__ .loading .d1 {
  width: 55px;
  height: 55px;
  position: absolute;
  top: -9px;
  border-left-color: transparent;
  border-right-color: transparent;
  animation: load161 1s linear infinite;
}

.__UIV_SCOPE__ .loading .d2 {
  width: 40px;
  height: 40px;
  border-top-color: transparent;
  border-bottom-color: transparent;
  margin: 7.5px;
  animation: load2812 2s linear infinite;
}

@keyframes load161 {
  0% {
    transform: rotate(0);
  }

  100% {
    transform: rotate(360deg);
  }
}

@keyframes load2812 {
  0% {
    transform: rotate(0);
  }

  100% {
    transform: rotate(-360deg);
  }
}
